factorial.code:
int factorial(int n) => n <= 1 ? 1 : n * factorial(n - 1);

void main() {
  print(factorial(10));
}

fizzbuzz.code:
void main() {
  for (var i = 1; i <= 15; i++) {
    // A switch expression over a record of remainders (Dart 3 patterns).
    final word = switch ((i % 3, i % 5)) {
      (0, 0) => 'FizzBuzz',
      (0, _) => 'Fizz',
      (_, 0) => 'Buzz',
      _ => '$i',
    };
    print(word);
  }
}

higher-order.code:
void main() {
  final numbers = List.generate(10, (i) => i + 1);

  // where = filter; both return lazy Iterables, forced by join.
  final squares = numbers.where((n) => n.isEven).map((n) => n * n);
  print(squares.join(' '));
}

shapes.code:
sealed class Shape {}

final class Rectangle extends Shape {
  final int width, height;
  Rectangle(this.width, this.height);
}

final class Triangle extends Shape {
  final int base, height;
  Triangle(this.base, this.height);
}

// Shape is sealed, so the compiler checks that this switch is exhaustive.
int area(Shape shape) => switch (shape) {
  Rectangle(:final width, :final height) => width * height,
  Triangle(:final base, :final height) => base * height ~/ 2,
};

void main() {
  print('Rectangle: ${area(Rectangle(3, 4))}');
  print('Triangle: ${area(Triangle(10, 3))}');
}

signature.code:
import 'dart:isolate';

var calls = 0; // top-level state: each isolate has its own copy

int fib(int n) {
  calls++;
  return n < 2 ? n : fib(n - 1) + fib(n - 2);
}

// async* returns a Stream: values arrive over time, consumed with await for.
Stream<String> results(List<int> inputs) async* {
  for (final n in inputs) {
    // Run the closure in a fresh isolate; only the result comes back, as a message.
    final (value, count) = await Isolate.run(() => (fib(n), calls));
    yield 'fib($n) = $value after $count calls in its isolate';
  }
}

Future<void> main() async {
  await for (final line in results([10, 20])) {
    print(line);
  }
  print('calls made in the main isolate: $calls');
}
